//! THE LIVE-CUTOVER ALLOWLIST, against the SHARED case matrix the web is tested on.
//!
//! `lib/engine-live-allowlist-cases.json` -- 324 cases of
//! (riskAuthority x riskAuthorityDemoOnly x engineLiveAllowlistOn x accountMode x engineLiveEnabled)
//! -> (modeAllowed, owner), generated by the web and read HERE BY THE SAME PATH, so after the branches
//! merge it is literally one file. That is the point: three implementations of one rule
//! (lib/risk-authority.ts, this engine, the gateway's src/ingress-scope.ts) can only be kept honest by
//! one table none of them owns. See docs/ENGINE-LIVE-ALLOWLIST.md.
//!
//! DORMANT. Every case with the flag off or the entry off must resolve to exactly the pre-cutover
//! answer, and `flag_off_is_byte_for_byte_the_old_rule` below asserts that against the OLD rule written
//! out verbatim, so "nothing changed while it is off" is proved rather than asserted.

use order_management::authority::{risk_owner_of, RiskOwner};
use order_management::ingress;

#[derive(serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    risk_authority: Option<String>,
    risk_authority_demo_only: Option<bool>,
    engine_live_allowlist_on: Option<bool>,
    account_mode: Option<String>,
    engine_live_enabled: Option<bool>,
    mode_allowed: bool,
    owner: String,
}

fn cases() -> Vec<Case> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../lib/engine-live-allowlist-cases.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("engine-live-allowlist-cases.json")).expect("parses")
}

/// The engine's `engine_live_allowed` over the case's two columns: `None` (a SQL NULL, or a database
/// without the migration) is `false`, which is the fail-closed answer the contract asks for.
fn engine_live(c: &Case) -> bool {
    ingress::engine_live_allowed(
        c.account_mode.as_deref().unwrap_or(""),
        c.engine_live_allowlist_on.unwrap_or(false),
        c.engine_live_enabled.unwrap_or(false),
    )
}

#[test]
fn every_shared_case_agrees_with_the_web_on_mode_allowed_and_owner() {
    // A scope must be installed or `mode_allowed` short-circuits to true for everything -- the matrix
    // is written for a scoped engine, which is the only shape production runs in (main.rs refuses to
    // start the order path in live mode without a list).
    ingress::restrict_to(vec!["cfg-assert-account".to_string()]);
    assert!(ingress::restricted(), "the matrix only means anything with a scope installed");

    let cases = cases();
    assert_eq!(cases.len(), 324, "the shared matrix changed: re-read it rather than quietly covering less");

    let mut allowed_true = 0;
    let mut rust = 0;
    for (i, c) in cases.iter().enumerate() {
        let mode = c.account_mode.as_deref().unwrap_or("");

        let got_allowed = ingress::mode_allowed(
            mode,
            c.engine_live_allowlist_on.unwrap_or(false),
            c.engine_live_enabled.unwrap_or(false),
        );
        assert_eq!(
            got_allowed, c.mode_allowed,
            "case {i}: mode_allowed({mode}, flag={:?}, entry={:?}) = {got_allowed}, the web says {}",
            c.engine_live_allowlist_on, c.engine_live_enabled, c.mode_allowed
        );

        let got_owner = risk_owner_of(
            c.risk_authority.as_deref(),
            c.risk_authority_demo_only,
            c.account_mode.as_deref(),
            Some(engine_live(c)),
        );
        let want = if c.owner == "RUST" { RiskOwner::Rust } else { RiskOwner::Web };
        assert_eq!(
            got_owner, want,
            "case {i}: risk_owner_of(auth={:?}, demoOnly={:?}, mode={:?}, engineLive={}) = {got_owner:?}, the web says {}",
            c.risk_authority, c.risk_authority_demo_only, c.account_mode, engine_live(c), c.owner
        );

        if c.mode_allowed { allowed_true += 1 }
        if c.owner == "RUST" { rust += 1 }
    }
    // the matrix must actually exercise both answers on both questions, or agreeing with it is empty
    assert!(allowed_true > 0 && allowed_true < cases.len(), "modeAllowed is constant across the matrix ({allowed_true}/{})", cases.len());
    assert!(rust > 0 && rust < cases.len(), "owner is constant across the matrix ({rust}/{})", cases.len());
}

/// THE DORMANCY PROOF. The pre-cutover rules, written out verbatim, against the new ones over every
/// case: with the flag off, or the entry off, or the columns absent, the two must agree EXACTLY. This
/// is what "flag-off is today's behaviour" means, and it is checked rather than claimed.
#[test]
fn flag_off_is_byte_for_byte_the_old_rule() {
    ingress::restrict_to(vec!["cfg-assert-account".to_string()]);

    // verbatim from before the cutover (ingress.rs / authority.rs at 9895f841)
    fn old_mode_allowed(account_mode: &str) -> bool { account_mode == "DEMO" }
    fn old_owner(authority: Option<&str>, demo_only: Option<bool>, account_mode: Option<&str>) -> RiskOwner {
        if authority != Some("RUST") { return RiskOwner::Web }
        let demo = match account_mode { Some("DEMO") => true, Some("LIVE") => false, _ => return RiskOwner::Web };
        let demo_only = demo_only != Some(false);
        if !demo_only || demo { RiskOwner::Rust } else { RiskOwner::Web }
    }

    let mut checked = 0;
    let mut differ = 0;
    for c in cases() {
        let mode = c.account_mode.as_deref().unwrap_or("");
        let flag = c.engine_live_allowlist_on.unwrap_or(false);
        let entry = c.engine_live_enabled.unwrap_or(false);

        let new_allowed = ingress::mode_allowed(mode, flag, entry);
        let new_owner = risk_owner_of(c.risk_authority.as_deref(), c.risk_authority_demo_only, c.account_mode.as_deref(), Some(engine_live(&c)));
        let was_allowed = old_mode_allowed(mode);
        let was_owner = old_owner(c.risk_authority.as_deref(), c.risk_authority_demo_only, c.account_mode.as_deref());

        if !flag || !entry || mode != "LIVE" {
            // dormant: every one of these must be identical to the old rule
            assert_eq!(new_allowed, was_allowed, "flag={flag} entry={entry} mode={mode}: mode_allowed changed while dormant");
            assert_eq!(new_owner, was_owner, "flag={flag} entry={entry} mode={mode}: owner changed while dormant");
            checked += 1;
        } else if new_allowed != was_allowed || new_owner != was_owner {
            differ += 1;
        }
    }
    assert!(checked > 250, "expected the overwhelming majority of the matrix to be dormant, got {checked}");
    // and the ONLY cases that may differ are flag on + entry on + LIVE, which is the feature itself
    assert!(differ > 0, "the allowlist changes nothing at all even when fully on -- the rule is not wired");
    println!("dormant and identical on {checked} cases; {differ} differ, all of them flag-on + entry-on + LIVE");
}

/// The environment list alone must NEVER admit a LIVE account. That is the L2 Step 3 finding: a live id
/// was put ON the list and FILLED, because the list was the only condition. The list narrows; only the
/// two columns admit.
#[test]
fn the_ingress_list_alone_never_admits_a_live_account() {
    ingress::restrict_to(vec!["live-account-id".to_string()]);
    assert!(ingress::allows("live-account-id"), "the id is on the list");
    assert!(!ingress::mode_allowed("LIVE", false, false), "on the list, flag off, no entry -> refused");
    assert!(!ingress::mode_allowed("LIVE", true, false), "flag on but no entry -> refused");
    assert!(!ingress::mode_allowed("LIVE", false, true), "entry on but flag off -> refused");
    assert!(ingress::mode_allowed("LIVE", true, true), "both on -> admitted (the feature, dormant in production)");
    assert!(ingress::mode_allowed("DEMO", false, false), "a DEMO account is unaffected by any of it");
}
